package com.nthexperience.desktop;

import android.content.*;
import android.graphics.*;
import android.net.Uri;
import android.os.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.concurrent.*;

/** Draft-only wallpaper settings. Selection is previewed; Save changes applies it. */
final class BackgroundPicker extends LinearLayout {
    private final DesktopStore store;private final JSONObject draft;private final Runnable browse,apply;private final AeroWallpaper preview;
    private final ExecutorService worker=Executors.newSingleThreadExecutor();private final Handler main=new Handler(Looper.getMainLooper());private CancellationSignal signal=new CancellationSignal();private Bitmap image;private int originalW,originalH;private boolean closed,pictureReady;private TextView save;
    private static final String[] THEMES={"Aero","Twilight","Meadow","Seven Blue"};
    static final String[] POSITIONS={"Fill","Fit","Stretch","Tile","Center"};
    static final int[] COLORS={0xff0a263b,0xff000000,0xffe5edf2,0xff374d42,0xff40344d,0xff6a5135};
    BackgroundPicker(Context context,DesktopStore store,JSONObject draft,Runnable browse,Runnable apply){super(context);this.store=store;this.draft=draft;this.browse=browse;this.apply=apply;setOrientation(VERTICAL);if(!draft.has("theme")){put("theme",store.prefs.getInt("wallpaper",AeroWallpaper.SEVEN));put("uri",store.prefs.getString("wallpaper_photo",""));put("position",store.prefs.getString("wallpaper_position","Fill"));put("background",store.prefs.getInt("wallpaper_bg",0));}
        addView(Aero.text(context,"Choose a desktop background",21,0xff2e682e));TextView hint=Aero.text(context,"Choose a picture and how it should appear on your desktop.",12,0xff4e6676);hint.setPadding(0,Aero.dp(context,8),0,Aero.dp(context,10));addView(hint);
        LinearLayout location=new LinearLayout(context);TextView label=Aero.text(context,"Picture location: ",12,Aero.INK);location.addView(label,new LayoutParams(0,-1,1));location.addView(Aero.button(context,"Browse…",browse),new LayoutParams(-2,Aero.dp(context,44)));addView(location);TextView folder=Aero.text(context,draft.optString("uri").isEmpty()?"Nth Desktop backgrounds":"Your selected picture",12,0xff42647b);folder.setContentDescription("Background picture location");addView(folder);
        GridLayout gallery=new GridLayout(context);gallery.setColumnCount(4);for(int i=0;i<THEMES.length;i++){final int theme=i;LinearLayout tile=Aero.column(context);AeroWallpaper thumb=new AeroWallpaper(context,theme,false);tile.addView(thumb,new LayoutParams(-1,Aero.dp(context,64)));TextView name=Aero.text(context,THEMES[i],11,Aero.INK);name.setGravity(Gravity.CENTER);tile.addView(name);tile.setPadding(Aero.dp(context,3),Aero.dp(context,3),Aero.dp(context,3),Aero.dp(context,3));tile.setTag(theme);tile.setBackground(theme==draft.optInt("theme")&&draft.optString("uri").isEmpty()?Aero.panel(context,0xffe5f3ff,0xffd0e7f6,2,0xff75a8c8):Aero.selection(context));tile.setContentDescription("Preview background: "+THEMES[i]);tile.setOnClickListener(v->{put("theme",theme);put("uri","");pictureReady=true;if(save!=null)save.setEnabled(true);folder.setText("Nth Desktop backgrounds");for(int n=0;n<gallery.getChildCount();n++){View other=gallery.getChildAt(n);other.setBackground(Integer.valueOf(theme).equals(other.getTag())?Aero.panel(context,0xffe5f3ff,0xffd0e7f6,2,0xff75a8c8):Aero.selection(context));}showPreview();});GridLayout.LayoutParams size=new GridLayout.LayoutParams();size.columnSpec=GridLayout.spec(GridLayout.UNDEFINED,1f);size.width=0;gallery.addView(tile,size);}addView(gallery,new LayoutParams(-1,-2));
        preview=new AeroWallpaper(context,draft.optInt("theme"),false);preview.setContentDescription("Desktop background preview");preview.setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_YES);addView(preview,new LayoutParams(-1,Aero.dp(context,130)));
        addView(Aero.text(context,"How should the picture be positioned?",13,Aero.INK));Spinner position=new Spinner(context);position.setContentDescription("Picture position");position.setAdapter(new ArrayAdapter<>(context,android.R.layout.simple_spinner_dropdown_item,POSITIONS));for(int i=0;i<POSITIONS.length;i++)if(POSITIONS[i].equals(draft.optString("position")))position.setSelection(i);position.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int at,long id){put("position",POSITIONS[at]);showPreview();}});addView(position,new LayoutParams(-1,Aero.dp(context,44)));
        LinearLayout colors=new LinearLayout(context);for(int i=0;i<COLORS.length;i++){final int index=i;TextView color=Aero.text(context,"",12,Aero.INK);color.setBackground(Aero.panel(context,COLORS[i],COLORS[i],2,0xff8da9b9));color.setContentDescription("Background colour "+(i+1));color.setFocusable(true);color.setOnClickListener(v->{put("background",index);showPreview();});LayoutParams size=new LayoutParams(0,Aero.dp(context,36),1);size.setMargins(Aero.dp(context,3),Aero.dp(context,5),Aero.dp(context,3),Aero.dp(context,7));colors.addView(color,size);}addView(colors);
        save=Aero.button(context,"Save changes",()->{if(!draft.optString("uri").isEmpty()&&!pictureReady)return;store.prefs.edit().putInt("wallpaper",draft.optInt("theme",AeroWallpaper.SEVEN)).putString("wallpaper_photo",draft.optString("uri")).putString("wallpaper_position",draft.optString("position","Fill")).putInt("wallpaper_bg",draft.optInt("background",0)).apply();apply.run();Toast.makeText(context,"Desktop background updated",Toast.LENGTH_SHORT).show();});save.setEnabled(draft.optString("uri").isEmpty());addView(save);addView(Aero.button(context,"Cancel changes",()->{draft.remove("theme");draft.remove("uri");draft.remove("position");draft.remove("background");Toast.makeText(context,"Preview discarded",Toast.LENGTH_SHORT).show();apply.run();}));loadPicture();
    }
    private void put(String key,Object value){GadgetLayout.put(draft,key,value);}
    private void showPreview(){if(preview!=null)preview.draft(draft.optInt("theme",AeroWallpaper.SEVEN),draft.optString("uri").isEmpty()?null:image,originalW,originalH,draft.optString("position","Fill"),COLORS[Math.max(0,Math.min(COLORS.length-1,draft.optInt("background",0)))]);}
    private void loadPicture(){String uri=draft.optString("uri");if(uri.isEmpty()){showPreview();return;}CancellationSignal request=signal;worker.execute(()->{PhotoImage decoded=null;try{decoded=PhotoImage.read(getContext().getApplicationContext(),Uri.parse(uri),request,1024,800000);}catch(Exception|OutOfMemoryError ignored){}PhotoImage result=decoded;main.post(()->{if(closed||request.isCanceled()||!uri.equals(draft.optString("uri"))){if(result!=null)result.bitmap.recycle();return;}if(result!=null){pictureReady=true;save.setEnabled(true);image=result.bitmap;originalW=result.width;originalH=result.height;showPreview();}else{addView(Aero.text(getContext(),"Picture unavailable. Choose it again with Browse before saving.",12,0xff8e352b));pictureReady=false;save.setEnabled(false);showPreview();}});});}
    @Override protected void onDetachedFromWindow(){closed=true;signal.cancel();worker.shutdownNow();main.removeCallbacksAndMessages(null);preview.close();image=null;super.onDetachedFromWindow();}
}
